// This file is generated by AI.

// 项目会话: 记住每个项目上次打开的本地文件类选项卡 (场景/资源/配置), 下次打开时恢复。
//
// 这类选项卡都有本地实体, 可复原; 临时工具页 (差异、说明、工作台) 不保存。
// 存的是路径而不是内容 —— 内容永远以磁盘为准。

import { bindingKey } from './bindings';
import type { ResourceKind } from '../tabs/model';

export type LocalTabEntry = {
  kind: 'scene' | 'resource' | 'config';
  path: string;
  resourceKind?: ResourceKind;
};

export interface ProjectSession {
  /** 已打开的本地文件类选项卡, 按选项卡顺序 */
  tabs: LocalTabEntry[];
  /** 上次激活的那个本地文件; null 表示当时激活的不是本地文件类选项卡 */
  activeTab: string | null;
  updatedAt: number;
}

/** 单个项目最多恢复多少个选项卡 */
export const SESSION_TAB_LIMIT = 20;
/** 最多记住多少个项目 (超出的按最近更新淘汰) */
export const SESSION_PROJECT_LIMIT = 50;

const STORAGE_KEY = 'webgal-ink.sessions';

/** 选项卡的最小形状 (只取恢复需要的字段, 免得这个模块依赖选项卡模型) */
interface TabLike {
  id: string;
  kind: string;
  /** 只有场景/资源/配置类选项卡带路径 (工作台、说明页没有) */
  path?: string;
  resourceKind?: ResourceKind;
}

/**
 * 从选项卡序列里取出要恢复的本地文件类选项卡 (按显示顺序, 去重, 截断)。
 */
export function collectLocalTabs(tabs: readonly TabLike[]): LocalTabEntry[] {
  const seen = new Set<string>();
  const entries: LocalTabEntry[] = [];
  for (const tab of tabs) {
    if (!tab.path) continue;
    const kind = tab.kind as LocalTabEntry['kind'];
    if (kind !== 'scene' && kind !== 'resource' && kind !== 'config') continue;
    const key = `${kind}:${tab.path.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const entry: LocalTabEntry = { kind, path: tab.path };
    if (kind === 'resource' && tab.resourceKind) entry.resourceKind = tab.resourceKind;
    entries.push(entry);
    if (entries.length >= SESSION_TAB_LIMIT) break;
  }
  return entries;
}

/** 兼容旧会话格式的场景路径列表。 */
export function collectSceneTabs(tabs: readonly TabLike[]): string[] {
  return collectLocalTabs(tabs)
    .filter((entry) => entry.kind === 'scene')
    .map((entry) => entry.path);
}

/** 由当前选项卡状态算出要保存的会话。 */
export function sessionFromTabs(tabs: readonly TabLike[], activeTabId: string | null): ProjectSession {
  const active = tabs.find((tab) => tab.id === activeTabId);
  return {
    tabs: collectLocalTabs(tabs),
    activeTab:
      active && active.path && (active.kind === 'scene' || active.kind === 'resource' || active.kind === 'config')
        ? active.path
        : null,
    updatedAt: Date.now(),
  };
}

function normalizeEntry(item: unknown): LocalTabEntry | null {
  if (typeof item === 'string' && item.trim()) {
    return { kind: 'scene', path: item };
  }
  if (!item || typeof item !== 'object') return null;
  const record = item as Partial<LocalTabEntry>;
  if (typeof record.path !== 'string' || !record.path.trim()) return null;
  const kind = record.kind;
  if (kind !== 'scene' && kind !== 'resource' && kind !== 'config') return null;
  if (
    kind === 'resource' &&
    (!record.resourceKind || !['image', 'audio', 'video', 'text'].includes(record.resourceKind))
  ) {
    return { kind: 'resource', path: record.path, resourceKind: 'text' };
  }
  return {
    kind,
    path: record.path,
    ...(kind === 'resource' && record.resourceKind ? { resourceKind: record.resourceKind } : {}),
  };
}

/** 清理持久化里读到的对象; 结构不对时返回 null。 */
export function normalizeSession(raw: unknown): ProjectSession | null {
  if (!raw || typeof raw !== 'object') return null;
  const record = raw as Partial<ProjectSession>;
  if (!Array.isArray(record.tabs)) return null;
  const tabs: LocalTabEntry[] = [];
  const seen = new Set<string>();
  for (const item of record.tabs) {
    const entry = normalizeEntry(item);
    if (!entry) continue;
    const key = `${entry.kind}:${entry.path.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    tabs.push(entry);
    if (tabs.length >= SESSION_TAB_LIMIT) break;
  }
  return {
    tabs,
    activeTab: typeof record.activeTab === 'string' && record.activeTab.trim() ? record.activeTab : null,
    updatedAt: Number.isFinite(record.updatedAt) ? Number(record.updatedAt) : 0,
  };
}

/** 读全部会话 (按项目路径规范化后的键索引)。 */
export function loadSessions(): Record<string, ProjectSession> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const sessions: Record<string, ProjectSession> = {};
    for (const [key, value] of Object.entries(parsed)) {
      const session = normalizeSession(value);
      if (session) sessions[key] = session;
    }
    return sessions;
  } catch {
    return {};
  }
}

/** 读某个项目的会话; 没有记录时返回 null。 */
export function loadSession(projectPath: string): ProjectSession | null {
  return loadSessions()[bindingKey(projectPath)] ?? null;
}

/** 写入某个项目的会话, 顺带按更新时间淘汰过旧的记录。 */
export function saveSession(projectPath: string, session: ProjectSession): void {
  try {
    const sessions = loadSessions();
    sessions[bindingKey(projectPath)] = session;
    const entries = Object.entries(sessions).sort((a, b) => b[1].updatedAt - a[1].updatedAt);
    const kept = Object.fromEntries(entries.slice(0, SESSION_PROJECT_LIMIT));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(kept));
  } catch {
    // 存储不可用时静默忽略: 恢复选项卡是锦上添花, 不该影响打开项目
  }
}

/** 删除某个项目的会话 (项目被移入回收站时用)。 */
export function removeSession(projectPath: string): void {
  try {
    const sessions = loadSessions();
    delete sessions[bindingKey(projectPath)];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  } catch {
    // 同上
  }
}
